  function filteredInvoices(){const search=$('expenseSearch').value.trim().toLowerCase(),type=$('expenseTypeFilter').value;return state.invoices.filter(x=>{const supplier=state.suppliers.find(s=>Number(s.id)===Number(x.supplier_id)&&(!s._profile_id||String(s._profile_id)===String(x._profile_id))),party=paymentParty(x);return x.status!=='cancelled'&&(!type||x.expense_type===type)&&(!search||`${x.invoice_number} ${supplier?.commercial_name||''} ${party.label} ${x._company||''} ${(x.vouchers||[]).map(v=>v.folio).join(' ')}`.toLowerCase().includes(search))})}
