  function renderTables(){const empty='<tr><td colspan="6" class="empty">Sin gastos para estos filtros.</td></tr>';$('invoiceRows').innerHTML=state.loaded.queue?(filteredInvoices().map(rowHtml).join('')||empty):'<tr><td colspan="6" class="empty">Presiona Buscar gastos.</td></tr>';const paid=state.reviewStatus==='paid';$('reviewRows').innerHTML=paid?(state.loaded.payments?paidPaymentsHtml():'<div class="empty">Presiona Cargar pagados.</div>'):(state.loaded.queue?paymentGroupsHtml():'<div class="empty">Presiona Cargar pendientes.</div>');if(state.loaded.queue)renderCreditNotes();bindActions();document.querySelectorAll('[data-use-credits-party]').forEach(x=>x.onclick=e=>e.stopPropagation());document.querySelectorAll('[data-payment-check]').forEach(x=>x.onchange=()=>renderPaymentSelection(false));document.querySelectorAll('[data-pay-invoice]').forEach(b=>b.onclick=()=>startPayment(Number(b.dataset.payInvoice)));document.querySelectorAll('[data-select-all-party]').forEach(box=>box.onchange=()=>{document.querySelectorAll('[data-payment-check]').forEach(x=>{if(`${x.dataset.profile}|${x.dataset.party}`===box.dataset.selectAllParty)x.checked=box.checked});renderPaymentSelection(false)});document.querySelectorAll('[data-select-party]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();const matching=[...document.querySelectorAll('[data-payment-check]')].filter(x=>`${x.dataset.profile}|${x.dataset.party}`===b.dataset.selectParty),selected=matching.filter(x=>x.checked);document.querySelectorAll('[data-payment-check]').forEach(x=>{if(`${x.dataset.profile}|${x.dataset.party}`!==b.dataset.selectParty)x.checked=false});if(!selected.length)matching.forEach(x=>x.checked=true);renderPaymentSelection(true)});if(!$('paymentModal').hidden)renderPaymentSelection(false)}
  function actions(x){const p=` data-profile="${x._profile_id||activeProfile}"`,icon=(kind,title,icon,extra='')=>`<button class="btn icon-action ${kind}" type="button" title="${title}" aria-label="${title}" ${extra}><i class="fa-solid ${icon}"></i></button>`;if(x.expense_type==='direct'&&!['paid','cancelled'].includes(x.status)&&!Number(x.applied_amount_mxn||0))return `<span class="expense-actions">${icon('secondary','Editar gasto','fa-pen',`data-edit-invoice="${x.id}"${p}`)}${icon('secondary','Agregar observación','fa-comment-dots',`data-observe-invoice="${x.id}"${p}`)}${icon('bad','Eliminar gasto','fa-trash-can',`data-delete-invoice="${x.id}"${p} data-number="${esc(x.invoice_number)}"`)}</span>`;if(x.status==='paid')return '<span class="expense-payment-state"><i class="fa-solid fa-circle-check"></i> Pagado</span>';if(Number(x.applied_amount_mxn||0)>0)return '<span class="expense-payment-state"><i class="fa-solid fa-arrow-right-arrow-left"></i> En pagos</span>';if(x.status==='cancelled')return '<span class="expense-payment-state muted">Cancelado</span>';return '—'}
  function bindActions(){document.querySelectorAll('[data-edit-invoice]').forEach(b=>b.onclick=()=>openExpenseEditor(Number(b.dataset.editInvoice),b.dataset.profile,false));document.querySelectorAll('[data-observe-invoice]').forEach(b=>b.onclick=()=>openExpenseEditor(Number(b.dataset.observeInvoice),b.dataset.profile,true));document.querySelectorAll('[data-delete-invoice]').forEach(b=>b.onclick=()=>deleteInvoice(Number(b.dataset.deleteInvoice),b.dataset.number,b.dataset.profile));document.querySelectorAll('[data-edit-paid-date]').forEach(b=>b.onclick=()=>correctPaidDate(Number(b.dataset.editPaidDate),b.dataset.profile,b.dataset.date));document.querySelectorAll('[data-edit-payment-date]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();correctPaymentDate(Number(b.dataset.editPaymentDate),b.dataset.profile,b.dataset.date)});document.querySelectorAll('[data-delete-payment]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();deletePayment(Number(b.dataset.deletePayment),b.dataset.profile)})}
  async function correctPaidDate(id,profile,current){const next=prompt('Nueva fecha de factura (AAAA-MM-DD):',current||'');if(next===null||next===current)return;if(!/^\d{4}-\d{2}-\d{2}$/.test(next)){alert('Usa el formato AAAA-MM-DD.');return}if(!confirm('Se corregirá únicamente la fecha documental de esta factura pagada. ¿Continuar?'))return;try{await api(`/invoices/${id}/paid-date`,{method:'PUT',body:JSON.stringify({invoice_date:next})},profile);await loadPayments()}catch(err){alert(err.message)}}
  async function correctPaymentDate(id,profile,current){const next=prompt('Nueva fecha de pago (AAAA-MM-DD):',current||'');if(next===null||next===current)return;if(!/^\\d{4}-\\d{2}-\\d{2}$/.test(next)){alert('Usa el formato AAAA-MM-DD.');return}if(!confirm(`Se cambiará la fecha del pago P-${id} y de sus facturas relacionadas. ¿Continuar?`))return;try{await api(`/payments/${id}/paid-date`,{method:'PUT',body:JSON.stringify({paid_on:next})},profile);await loadPayments();$('reviewLoadStatus').textContent=`Fecha del pago P-${id} actualizada.`}catch(err){alert(err.message)}}
  async function deletePayment(id,profile){if(!confirm(`¿Eliminar el pago P-${id}?\n\nSe eliminará solamente el movimiento de pago. Las facturas y sus conceptos NO se borrarán: volverán a Pendientes de pago. Esta acción quedará registrada en auditoría.`))return;try{await api(`/payments/${id}`,{method:'DELETE'},profile);await loadPayments();$('reviewLoadStatus').textContent=`Pago P-${id} eliminado. Sus facturas y conceptos se conservaron y regresaron a pendientes.`}catch(err){alert(`No se pudo eliminar el pago P-${id}: ${err.message}`)}}
  function renderVouchers(){const groups=Object.fromEntries((state.bootstrap.groups||[]).map(g=>[g.id,g.name])),zone=$('voucherZoneFilter').value;$('voucherZoneFilter').innerHTML='<option value="">Todas las zonas</option>'+(state.bootstrap.groups||[]).map(g=>`<option value="${g.id}" ${String(g.id)===zone?'selected':''}>${esc(g.name)}</option>`).join('');const rows=state.vouchers.filter(v=>!zone||String(v.group_id)===zone);$('voucherRows').className='checkbox-list';$('voucherRows').innerHTML=rows.map(v=>{const s=state.suppliers.find(x=>Number(x.id)===Number(v.supplier_id));return `<label class="checkbox-row"><input type="checkbox" value="${v.id}" data-amount="${Number(v.amount_mxn||0)}" data-voucher-check><span><strong>${esc(v.folio)}</strong><br><small>${esc(s?.commercial_name||'Proveedor')} · ${esc(groups[v.group_id]||'General')} · ${esc(v.created_by_name||'Gerente')}</small></span><strong>${money(v.amount_mxn)}</strong></label>`}).join('')||'<div class="empty">No hay vales pendientes en esta zona.</div>';document.querySelectorAll('[data-voucher-check]').forEach(x=>x.onchange=renderVoucherSelection);renderVoucherSelection()}
  function renderVoucherSelection(){const selected=[...document.querySelectorAll('[data-voucher-check]:checked')],total=selected.reduce((n,x)=>n+Number(x.dataset.amount||0),0);$('voucherSelectionCount').textContent=`${selected.length} seleccionado${selected.length===1?'':'s'}`;$('voucherSelectionTotal').textContent=`${money(total)} seleccionado`;$('voucherSelectionHint').textContent=selected.length?'Completa los datos de la factura para relacionarlos.':'Selecciona al menos un vale.'}
  function renderAdvances(){const rows=state.advances||[],grand=rows.reduce((sum,x)=>sum+Number(x.available_amount_mxn||0),0),groups=new Map;$('advanceGrandTotal').textContent=money(grand);$('advanceCount').textContent=`${rows.length} anticipo${rows.length===1?'':'s'} pendiente de factura`;for(const row of rows){const key=String(row.supplier_id);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(row)}$('advanceRows').innerHTML=[...groups.entries()].map(([supplierId,items])=>{const supplier=state.suppliers.find(x=>String(x.id)===supplierId),total=items.reduce((sum,x)=>sum+Number(x.available_amount_mxn||0),0);return `<details class="advance-group" open><summary><span><strong>${esc(supplier?.commercial_name||'Proveedor')}</strong><small>${items.length} anticipo${items.length===1?'':'s'} pendiente de factura</small></span><span><strong>${money(total)}</strong><button class="btn primary" type="button" data-apply-advances="${supplierId}">Relacionar factura</button></span></summary><div class="table-wrap"><table><thead><tr><th>Fecha pagada</th><th>Referencia</th><th>Pagado</th><th>Comprobado</th><th>Pendiente de factura</th><th>Acciones</th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(x.paid_on)}</td><td>${esc(x.reference||'Sin referencia')}<br><small>${esc(x.description||'')}</small></td><td>${money(x.amount_mxn)}</td><td>${money(x.applied_amount_mxn)}</td><td><strong>${money(x.available_amount_mxn)}</strong></td><td><button class="btn danger-link" type="button" data-delete-advance="${x.id}">Eliminar</button></td></tr>`).join('')}</tbody></table></div></details>`}).join('')||'<div class="empty">No hay anticipos pendiente de factura con factura.</div>';document.querySelectorAll('[data-apply-advances]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();openAdvanceApply(Number(b.dataset.applyAdvances))});document.querySelectorAll('[data-delete-advance]').forEach(b=>b.onclick=()=>deleteAdvance(Number(b.dataset.deleteAdvance)))}
  function openAdvanceApply(supplierId){const rows=state.advances.filter(x=>Number(x.supplier_id)===supplierId&&Number(x.available_amount_mxn)>0),supplier=state.suppliers.find(x=>Number(x.id)===supplierId);$('advanceApplySupplier').value=String(supplierId);$('advanceApplyProfile').value=String(activeProfile);$('advanceApplyTitle').textContent=`Relacionar factura · ${supplier?.commercial_name||'Proveedor'}`;$('advanceInvoiceDate').value=today;$('advanceInvoiceConcept').innerHTML='<option value="">Usar concepto del anticipo</option>'+state.concepts.filter(x=>x.status==='active').map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');$('advanceApplyOptions').innerHTML=rows.map(x=>`<label class="advance-apply-row"><input type="checkbox" data-advance-check value="${x.id}" data-available="${Number(x.available_amount_mxn)}"><span><strong>${esc(x.paid_on)} · ${money(x.available_amount_mxn)}</strong><small>${esc(x.reference||x.description||'Sin referencia')}</small></span><input data-advance-amount="${x.id}" type="text" inputmode="decimal" value="${Number(x.available_amount_mxn).toFixed(2)}" disabled aria-label="Monto a aplicar"></label>`).join('');$('advanceApplyModal').hidden=false;document.body.classList.add('modal-open');document.querySelectorAll('[data-advance-check]').forEach(box=>box.onchange=()=>{document.querySelector(`[data-advance-amount="${box.value}"]`).disabled=!box.checked;updateAdvanceApplyTotals()});document.querySelectorAll('[data-advance-amount]').forEach(input=>{input.oninput=()=>updateAdvanceApplyTotals();input.onblur=()=>formatMoneyInput(input)});updateAdvanceApplyTotals()}
  function closeAdvanceApply(){$('advanceApplyModal').hidden=true;$('advanceApplyForm').reset();$('advanceApplyOptions').innerHTML='';document.body.classList.toggle('modal-open',!$('paymentModal').hidden||!$('expenseEditModal').hidden)}
