  function renderBars(id,rows){const max=Math.max(...(rows||[]).map(x=>Number(x.amount)),1);$(id).innerHTML=(rows||[]).map(x=>`<div class="bar"><span>${esc(id==='statusBars'?label(x.label):x.label)}</span><i style="width:${Math.max(4,Number(x.amount)/max*100)}%"></i><strong>${money(x.amount)}</strong></div>`).join('')||'<div class="empty">Sin datos.</div>'}
  function renderAnalytics(){const a=state.analytics;$('analyticsTotal').textContent=money(a.totals.all);$('analyticsPaid').textContent=money(a.totals.paid);$('analyticsPending').textContent=money(a.totals.pending);$('analyticsAlerts').textContent=a.invoice_count??a.alert_total??0;const labels={duplicate_invoice_numbers:'Facturas repetidas',similar_invoices:'Posibles duplicados',pending_suppliers:'Proveedores por validar',vouchers_without_amount:'Vales sin monto',vouchers_not_invoiced:'Vales sin factura',accounting_payment_overdue:'Pagos atrasados'};$('alertSummary').className='';$('alertSummary').innerHTML=Object.entries(a.alerts||{}).map(([k,v])=>`<div class="${v?'alert':'muted'}"><strong>${v}</strong> · ${esc(labels[k]||k)}</div>`).join('')||'<div class="empty">Sin alertas.</div>';['supplier','status','zone','concept','month'].forEach(k=>renderBars(k==='month'?'monthBars':k+'Bars',a['by_'+k]));renderPie('zoneChart',a.by_zone);renderPie('conceptChart',a.by_concept);$('analyticsDetailRows').innerHTML=(a.detail||[]).map(x=>`<tr><td>${esc(x.invoice_date||'')}</td><td>${esc(x.supplier||'')}</td><td>${esc(x.concept||'')}</td><td>${esc(x.zone||'')}</td><td>${money(x.total_mxn)}</td><td>${esc(label(x.status))}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Sin datos para estos filtros.</td></tr>'}
  function renderPie(id,rows){const total=(rows||[]).reduce((s,x)=>s+Number(x.amount||0),0);if(!total){$(id).style.background='';$(id).innerHTML='Sin datos';return}let cursor=0;const colors=['#7a1e2c','#c99f58','#344258','#b85c50','#6b8e7b'];const stops=(rows||[]).slice(0,5).map((x,i)=>{const start=cursor;cursor+=Number(x.amount||0)/total*360;return `${colors[i%colors.length]} ${start}deg ${cursor}deg`}).join(',');$(id).style.background=`conic-gradient(${stops})`;$(id).textContent=''}
  function renderRecipientAccounts(){const recipient=state.recipients.find(x=>Number(x.id)===Number($('directRecipient').value)),accounts=(recipient?.accounts||[]).filter(x=>x.status!=='inactive');$('directRecipientAccount').innerHTML='<option value="">Selecciona nómina o tarjeta</option>'+accounts.map(x=>`<option value="${x.id}">${esc(x.account_type==='credit_card'?`Tarjeta de crédito · ${x.bank_name||'Banco'} · •••• ${x.card_last_four}`:`Nómina · ${x.bank_name||'Banco'} · ${x.account_number||''}`)}</option>`).join('')}
