  function selectedPayments(){return [...document.querySelectorAll('[data-payment-check]:checked')]}
  function updatePaymentDifference(){const selected=selectedPayments(),balanceCents=selected.reduce((sum,x)=>sum+Math.round(Number(x.dataset.balance||0)*100),0),paidCents=toCents($('paymentAmount').value),appliedCents=Number.isFinite(paidCents)?Math.min(Math.max(0,paidCents),balanceCents):0,differenceCents=Number.isFinite(paidCents)?paidCents-appliedCents:0;$('paymentAppliedAmount').textContent=money(appliedCents/100);$('paymentDifference').textContent=money(differenceCents/100)}
  function renderPaymentSelection(openModal=false){const selected=selectedPayments(),parties=new Set(selected.map(x=>`${x.dataset.profile}|${x.dataset.party}`)),grossCents=selected.reduce((sum,x)=>sum+Math.round(Number(x.dataset.balance||0)*100),0),creditCents=[...parties].reduce((sum,key)=>sum+state.invoices.filter(x=>x.expense_type==='credit_note'&&`${x._profile_id||activeProfile}|${paymentParty(x).key}`===key).reduce((s,x)=>s+Math.round(Number(x.total_mxn||0)*100),0),0),totalCents=Math.max(0,grossCents-creditCents);if(!selected.length)$('paymentModal').hidden=true;else if(openModal)$('paymentModal').hidden=false;$('paymentSelectionCount').textContent=`${selected.length} factura${selected.length===1?'':'s'} seleccionada${selected.length===1?'':'s'}`;$('paymentSelectionHint').textContent=parties.size>1?'Selecciona únicamente facturas del mismo destinatario.':`Saldo seleccionado${creditCents?` (menos notas de crédito ${money(creditCents/100)})`:''}: ${money(totalCents/100)}`;$('paymentAmount').value=totalCents?(totalCents/100).toFixed(2):'';$('paymentMethod').value='Transferencia';$('batchPaymentForm').querySelector('button[type="submit"]').disabled=parties.size>1;updatePaymentDifference();document.body.classList.toggle('modal-open',!$('paymentModal').hidden||!$('expenseEditModal').hidden)}
