  async function transition(id,action,total,profile){const payload={action};if(['observe','reject','cancel'].includes(action)){payload.observation=prompt(action==='observe'?'Observación para el gerente:':'Motivo:')||'';if(!payload.observation)return}if(action==='mark_paid'){payload.paid_on=prompt('Fecha de pago (AAAA-MM-DD):',today);payload.paid_amount_mxn=Number(prompt('Monto pagado:',String(total)));if(!payload.paid_on||!payload.paid_amount_mxn)return}try{await api(`/invoices/${id}/transition`,{method:'POST',body:JSON.stringify(payload)},profile);await loadInvoices()}catch(e){alert(e.message)}}
  async function deleteInvoice(id,number,profile){const row=state.invoices.find(x=>Number(x.id)===id&&String(x._profile_id||activeProfile)===String(profile||activeProfile)),question=row?.expense_type==='credit_note'?`¿Eliminar la nota de crédito ${number}?`:`¿Eliminar el gasto ${number}?`;if(!confirm(`${question}\n\nSe quitará de gastos, pendientes de pago y totales. Quedará únicamente la huella de auditoría.`))return;try{await api(`/invoices/${id}`,{method:'DELETE'},profile)}catch(error){alert(`No se pudo eliminar ${number}: ${error.message}`);return}state.invoices=state.invoices.filter(x=>Number(x.id)!==id||String(x._profile_id||activeProfile)!==String(profile||activeProfile));renderTables();$('queueLoadStatus').textContent=`Movimiento ${number} eliminado.`;$('reviewLoadStatus').textContent=`Movimiento ${number} eliminado.`}
  function openExpenseEditor(id,profile,observationOnly=false){const row=state.invoices.find(x=>Number(x.id)===id&&String(x._profile_id||activeProfile)===String(profile||activeProfile));if(!row)return;$('expenseEditId').value=String(id);$('expenseEditProfile').value=String(profile||activeProfile);$('expenseEditFolio').value=row.invoice_number||'';$('expenseEditDate').value=row.invoice_date||'';$('expenseEditTotal').value=Number(row.total_mxn||0).toFixed(2);$('expenseEditDescription').value=row.description||'';$('expenseEditObservation').value=row.observation||'';$('expenseEditTitle').textContent=observationOnly?'Agregar observación':`Editar ${row.expense_type==='credit_note'?'nota de crédito':'gasto'} ${row.invoice_number}`;$('expenseEditModal').hidden=false;document.body.classList.add('modal-open');setTimeout(()=>$(observationOnly?'expenseEditObservation':'expenseEditFolio').focus(),0)}
  function closeExpenseEditor(){$('expenseEditModal').hidden=true;$('expenseEditForm').reset();document.body.classList.toggle('modal-open',!$('paymentModal').hidden)}
