  $('advanceApplyForm').onsubmit=async e=>{e.preventDefault();try{const checked=[...document.querySelectorAll('[data-advance-check]:checked')];if(!checked.length)throw new Error('Selecciona al menos un anticipo.');const allocations=checked.map(box=>{const amount=parseMoney(document.querySelector(`[data-advance-amount="${box.value}"]`).value),available=Number(box.dataset.available||0);if(!Number.isFinite(amount)||amount<=0||amount>available+.005)throw new Error(`El monto del anticipo no puede superar ${money(available)}.`);return{advance_id:Number(box.value),amount_mxn:amount}}),total=parseMoney($('advanceInvoiceTotal').value),applied=allocations.reduce((sum,x)=>sum+x.amount_mxn,0);if(!Number.isFinite(total)||total<=0)throw new Error('Captura el total de la factura.');if(applied>total+.005)throw new Error('Los anticipos seleccionados superan el total de la factura.');const first=state.advances.find(x=>Number(x.id)===allocations[0].advance_id);await api('/advances/apply',{method:'POST',body:JSON.stringify({supplier_id:Number($('advanceApplySupplier').value),concept_id:Number($('advanceInvoiceConcept').value)||first?.concept_id||null,expense_zone_id:first?.expense_zone_id||null,invoice_number:$('advanceInvoiceNumber').value,invoice_date:$('advanceInvoiceDate').value,total_mxn:total,description:$('advanceInvoiceDescription').value,allocations})},$('advanceApplyProfile').value);closeAdvanceApply();await loadAdvances();$('advanceRows').insertAdjacentHTML('afterbegin','<div class="status">Factura relacionada. El saldo restante ya aparece en Pagos.</div>')}catch(err){alert(err.message)}};
