function renderPaymentSelection(openModal=false){const selected=selectedPayments(),parties=new Set(selected.map(x=>`${x.dataset.profile}|${x.dataset.party}`)),grossCents=selected.reduce((sum,x)=>sum+Math.round(Number(x.dataset.balance||0)*100),0);const creditCents=[...parties].reduce((sum,key)=>{const option=[...document.querySelectorAll('[data-use-credits-party]')].find(x=>x.dataset.useCreditsParty===key);return sum+(option?.checked?state.invoices.filter(x=>x.expense_type==='credit_note'&&`${x._profile_id||activeProfile}|${paymentParty(x).key}`===key).reduce((s,x)=>s+Math.round(Number(x.total_mxn||0)*100),0):0)},0),totalCents=Math.max(0,grossCents-creditCents);if(!selected.length)$('paymentModal').hidden=true;else if(openModal)$('paymentModal').hidden=false;$('paymentSelectionCount').textContent=`${selected.length} factura${selected.length===1?'':'s'} seleccionada${selected.length===1?'':'s'}`;$('paymentSelectionHint').textContent=parties.size>1?'Selecciona únicamente facturas del mismo destinatario.':`Saldo seleccionado${creditCents?` (menos notas de crédito ${money(creditCents/100)})`:''}: ${money(totalCents/100)}`;$('paymentAmount').value=totalCents?(totalCents/100).toFixed(2):'';$('paymentMethod').value='Transferencia';$('batchPaymentForm').querySelector('button[type="submit"]').disabled=parties.size>1;updatePaymentDifference();document.body.classList.toggle('modal-open',!$('paymentModal').hidden||!$('expenseEditModal').hidden)}
$('batchPaymentForm').onsubmit=async e=>{e.preventDefault();const selected=selectedPayments();if(!selected.length)return;const profile=selected[0].dataset.profile,amountCents=toCents($('paymentAmount').value),balances=selected.map(x=>Math.round(Number(x.dataset.balance||0)*100)),total=balances.reduce((a,b)=>a+b,0);if(!Number.isFinite(amountCents)||amountCents<=0){alert('Escribe un monto pagado válido mayor a $0.00.');return}let remaining=Math.min(amountCents,total);const invoice_allocations=selected.map((x,i)=>{const applied=i===selected.length-1?Math.min(remaining,balances[i]):Math.min(balances[i],Math.round(Math.min(amountCents,total)*(balances[i]/total)));remaining-=applied;return{invoice_id:Number(x.value),amount_mxn:applied/100}}).filter(x=>x.amount_mxn>0);const credit_note_ids=[...document.querySelectorAll('[data-use-credits-party]:checked')].flatMap(box=>state.invoices.filter(x=>x.expense_type==='credit_note'&&`${x._profile_id||activeProfile}|${paymentParty(x).key}`===box.dataset.useCreditsParty).map(x=>Number(x.id)));try{await api('/payments',{method:'POST',body:JSON.stringify({invoice_allocations,credit_note_ids,paid_on:$('paymentDate').value,amount_mxn:amountCents/100,method:'Transferencia',reference:$('paymentReference').value,notes:$('paymentNotes').value})},profile);e.target.reset();$('paymentDate').value=today;await loadInvoices('',false)}catch(err){alert(err.message)}};
document.addEventListener('change',event=>{if(event.target.matches('[data-use-credits-party]'))renderPaymentSelection(false)});
